    <script>
        // DOM加载完成后执行
        document.addEventListener('DOMContentLoaded', function() {

            // --- 1. 图片画廊交互 ---
            const mainImage = document.getElementById('media_image_image');
            const thumbnails = document.querySelectorAll('.gallery-thumbnail');

            thumbnails.forEach(thumb => {
                thumb.addEventListener('click', function() {
                    // 1. 更新主图片的src
                    const newSrc = this.getAttribute('data-img');
                    mainImage.src = newSrc;

                    // 2. 更新所有缩略图的active类
                    thumbnails.forEach(t => t.classList.remove('active'));
                    this.classList.add('active');

                    // 3. 添加一个简单的视觉反馈（可选）
                    mainImage.style.opacity = '0.7';
                    setTimeout(() => {
                        mainImage.style.opacity = '1';
                    }, 150);
                });
            });

            // --- 2. 音频控件交互 ---
            const audioPlayer = document.getElementById('media_audio_track');
            const playPauseBtn = document.getElementById('audio_control_playpause');
            const muteBtn = document.getElementById('audio_control_mute');

            if(playPauseBtn) {
                playPauseBtn.addEventListener('click', function() {
                    if(audioPlayer.paused) {
                        audioPlayer.play();
                        this.textContent = '暂停';
                    } else {
                        audioPlayer.pause();
                        this.textContent = '播放';
                    }
                });
            }

            if(muteBtn) {
                muteBtn.addEventListener('click', function() {
                    audioPlayer.muted = !audioPlayer.muted;
                    this.textContent = audioPlayer.muted ? '取消静音' : '静音';
                });
            }

            // --- 3. 表单提交处理 ---
            const contactForm = document.getElementById('contact_form_feedback');
            if(contactForm) {
                contactForm.addEventListener('submit', function(event) {
                    event.preventDefault(); // 阻止默认提交

                    // 简单的前端验证
                    const name = document.getElementById('form_input_name').value.trim();
                    const email = document.getElementById('form_input_email').value.trim();
                    const message = document.getElementById('form_textarea_message').value.trim();

                    if(!name || !email || !message) {
                        alert('请填写所有必填字段！');
                        return;
                    }

                    // 模拟提交成功
                    const submitBtn = document.getElementById('form_button_submit');
                    const originalText = submitBtn.textContent;
                    submitBtn.textContent = '提交中...';
                    submitBtn.disabled = true;

                    setTimeout(() => {
                        alert(`感谢 ${name} 的反馈！我们会尽快处理您的信息。`);
                        contactForm.reset();
                        submitBtn.textContent = originalText;
                        submitBtn.disabled = false;
                    }, 1000);
                });
            }

            // --- 4. 功能卡片悬停效果增强 (已在CSS中实现，这里添加一个控制台日志作为示例) ---
            const featureCards = document.querySelectorAll('.feature-card');
            featureCards.forEach(card => {
                card.addEventListener('mouseenter', function() {
                    console.log(`悬停在功能卡上: ${this.querySelector('h3').textContent}`);
                });
            });

            // --- 5. 设置页脚当前日期 ---
            const dateSpan = document.getElementById('current_date');
            if(dateSpan) {
                const now = new Date();
                const formattedDate = now.toLocaleDateString('zh-CN', {
                    year: 'numeric',
                    month: '2-digit',
                    day: '2-digit'
                });
                dateSpan.textContent = formattedDate;
            }
        });
    </script>
</body>
